    async def dispatch(self, name, args):
        if name == "progress":
            return self.team.progress.snapshot()
        if name == "record_progress":
            stage = args["milestone"]
            if stage not in {"entry", "tan_requested", "tan_received"}:
                raise ValueError("This milestone is recorded by runtime validation")
            observation = self.book.observations.get(args["observation_id"])
            if not observation or not args["quote"].strip() or args["quote"] not in observation["text"]:
                raise ValueError("Progress requires an exact observed quote")
            if stage in {"entry", "tan_requested"} and not same_origin(observation["url"], self.run["submission"]["url"]):
                raise ValueError("This milestone requires tender portal evidence")
            if stage.startswith("tan_") and not self.validation:
                raise ValueError("Validate the review before recording signing progress")
            self.team.progress.mark(stage, evidence_ids=[args["observation_id"]], source="agent_report")
            return self.team.progress.snapshot()
        if name == "browser":
            args = dict(args)
            reason = args.pop("reason", "")
            submission_action = args.pop("submission_action", False)
            control_info = getattr(self.browser, "control_info", {})
            info = control_info.get(args.get("ref"), {})
            field_info = ([control_info.get(field.get("ref"), {}) for field in args.get("fields", [])]
                          if args.get("operation") == "fill_fields" else [info])
            label = " ".join(str(info.get(key) or "") for key in ("text", "label"))
            signing = submission_action or (args.get("operation") in {"click", "press"} and
                re.search(r"signier|sign(?:\s+(?:bid|offer|and)|$)|submit\s+(?:bid|offer)|verbindlich\s+(?:abgeben|einreichen|senden)|tan\s+(?:anfordern|senden)", label, re.I))
            if signing and (self.prepare_only or self.validation is None):
                raise ValueError("Call validate_submission on the completed portal review before TAN/signing")
            target_pages = {args.get("page")}
            refs = [args.get("ref"), *[f.get("ref") for f in args.get("fields", [])]]
            for ref in refs:
                if ref in getattr(self.browser, "controls", {}):
                    target_pages.add(self.browser.controls[ref][0])
            if target_pages == {None} and args["operation"] not in {"pages", "new_tab", "new_context"}:
                if hasattr(self.browser, "preferred_page"):
                    target_pages.add(self.browser.preferred_page(args.get("browser", 0)))
                else:
                    target_pages.add(0)
            held = bool(target_pages.intersection(self.team.handoffs))
            if self.team.handoffs:
                target_browsers = {self.browser.browser_index(self.browser.page(p))
                                   for p in target_pages if p is not None}
                if args["operation"] in {"new_tab", "new_context"}:
                    target_browsers.add(args.get("browser", 0))
                held = held or any(self.browser.browser_index(self.browser.page(p)) in target_browsers
                                   for p in self.team.handoffs)
            if held and args["operation"] not in {
                    "pages", "observe", "screenshot"}:
                raise ValueError("Browser awaits human verification; re-observe after human completion")
            if args.get("ref") in self.recovery_suggestions.values():
                self.team.progress.metrics["suggestions_selected"] += 1
                self.recovery_suggestions = {p: ref for p, ref in self.recovery_suggestions.items() if ref != args["ref"]}
            result = await self.browser.act(**args)
            if isinstance(result, dict):
                await self.visual_check(result, reason)
                if result.get("interrupted_action", {}).get("executed") is False:
                    return result
            if signing:
                self.phase = "signing"
            # Editing calculated facts after review invalidates permission to sign.
            if self.validation and args.get("operation") in {"fill", "fill_fields", "select", "set_range"}:
                is_tan = bool(field_info) and all(re.search(r"\btan\b|one.?time|verification|bestätigungscode",
                    " ".join(str(field.get(k) or "") for k in ("text", "label", "name")), re.I)
                    for field in field_info)
                on_tender = isinstance(result, dict) and same_origin(result.get("url", ""), self.run["submission"]["url"])
                if not is_tan and on_tender:
                    self.validation = None
                    self.team.progress.mark("review", "pending", source="bid_edited")
            return result
        if name in {"research", "investigate"}:
            assignments = args.get("assignments") if name == "research" else [{
