/** Prints a run's logs from the start; following, polls with a growing pause until the run has ended. */
async function followLogs(ctx, runId, { follow, json }) {
  const minimum = Math.max(10, Number(process.env.ATIRA_POLL_MS) || 1000)
  let delay = minimum
  let cursor = 0
  let waiting = null
  for (;;) {
    const page = await getJson(ctx, `/v1/runs/${enc(runId)}/logs?after=${cursor}`)
    for (const chunk of page.chunks)
      process.stdout.write(
        json ? `${JSON.stringify({ at: chunk.at, stream: chunk.stream, text: chunk.text })}\n` : chunk.text,
      )
    cursor = page.cursor
    if (page.chunks.length >= 128) continue
    if (!follow) {
      // nothing logged yet: say where the run is, so an empty answer doesn't read as a broken run
      if (!cursor && !json) {
        const feed = await getJson(ctx, `/v1/runs/${enc(runId)}/feed?frames=0`)
        progress(
          feed.phase === "done"
            ? `Run ${runId} ended (${runWord(feed)}) without logs.`
            : `${queueText(feed) ?? `Run ${runId} is in ${feed.phase}`}: no logs yet. atira logs ${runId} --follow waits for them.`,
        )
      }
      return EXIT.ok
    }
    if (page.chunks.length) delay = minimum
    const feed = await getJson(ctx, `/v1/runs/${enc(runId)}/feed?frames=0`)
    // while it waits for a slot: its place in line, each time it changes
    const queued = queueText(feed)
    if (queued && queued !== waiting) progress(queued)
    waiting = queued
    if (feed.phase === "done" && feed.log_cursor <= cursor) {
      process.stderr.write(
        `\nRun ${runId} ended: ${feed.status === "submitted" ? "finished and scored. Test runs aren't ranked" : feed.status.replaceAll("_", " ")}${feed.error ? ` (${feed.error})` : ""}.\n`,
      )
      return ["failed", "timed_out"].includes(feed.status) ? EXIT.runFailed : EXIT.ok
    }
    await sleep(delay)
    delay = Math.min(delay * 2, minimum * 10)
  }
}

async function cancel({ args, json }) {
  const ctx = context()
  const runId = args[0].startsWith("reh_") ? await rehearsalRun(ctx, args[0]) : args[0]
  const result = await (await request(ctx, "POST", `/v1/runs/${enc(runId)}/cancel`)).json()
  output(json, result, `Cancelled ${result.run_id}: ${result.status} (${result.error}).`)
}

